class Alarms(AdminBaseClass):
    """Alarms"""
    def __init__(self):
        super(Alarms, self).__init__()
        self.parameters = Parameters()
        # self._load_alarm_description_json()
        self.alarm_details = list()

    @check_rat
    def verify_alarm(self, **kwargs):
        """This function searches for alarm
        :param faultid: fault id of the alarm
        :param rat: supported values l|w|g. The RAT which the alarm belongs to.
        :param alarm_type: active | history
        :param severity: Alarm severity (critical, major, minor or warning)
        :param should_exist: Should the alarm exist or not
        :param occurrences: The number of instances expected for the alarm
        :param check_unexpected_alarms: Boolean to validate unexpected alarms
                                        or not
        :param expected_alarms: A list of faultids which will be ignored during
                                validation
        :param prev_alarms: Alarms Json for validating against the current
                            alarms
        :param timeout: Time to wait for positive procedure result
        :param alias: Name of execution context
        :raises: exception based on should_exist argument
        """

        faultid = kwargs.get("faultid", None)
        alarm_type = kwargs.get("alarm_type", 'active')
        severity = kwargs.get("severity", None)
        should_exist = kwargs.get("should_exist", True)
        occurrences = kwargs.get("occurrences", 1)
        check_unexpected_alarms = kwargs.get("check_unexpected_alarms", False)
        expected_alarms = kwargs.get("expected_alarms", [])
        prev_alarms = kwargs.get("prev_alarms", None)
        load_history = kwargs.get("load_history", False)
        if len(expected_alarms) > 0:
            expected_alarms = [int(x) for x in expected_alarms]
        timeout = kwargs.get("timeout", 300)
        alias = kwargs.get("alias", 'default')
        if faultid:
            faultid = int(faultid)
        # should_exist = bool(should_exist)
        if isinstance(should_exist, str):
            should_exist = should_exist.lower() in ('true', '1', 'yes', 'on')
        else:
            should_exist = bool(should_exist)
        occurrences = int(occurrences)
        timeout = int(timeout)

        return getattr(self, "_verify_in_{}_alarms".format(
            alarm_type.lower()))(faultid, severity, should_exist, occurrences,
                                 check_unexpected_alarms, expected_alarms,
                                 prev_alarms, load_history, timeout, alias)

    def _verify_in_active_alarms(self, faultid, severity, should_exist,
                                 occurrences, check_unexpected_alarms,
                                 expected_alarms, prev_alarms, load_history,
                                 timeout, alias):
        logger.debug("Getting active alarms....")
        alarm_object_list = self.factory.admin.get_active_alarms(
            severity, timeout=timeout, connection=alias)
        self.alarm_details = alarm_object_list
        logger.info("alarms list {}".format(alarm_object_list))
        self._write_alarms_to_file('active_alarms.json', alarm_object_list)
        self._verify_alarm_exists_and_validate_with_rise(
            alarm_object_list, check_unexpected_alarms, prev_alarms,
            expected_alarms, faultid, occurrences, should_exist, alias)
        logger.info('alarms to be returned')
        logger.info(alarm_object_list)
        return alarm_object_list

    def _verify_in_history_alarms(self, faultid, severity, should_exist,
                                  occurrences, check_unexpected_alarms,
                                  expected_alarms, prev_alarms, load_history,
                                  timeout, alias):
        logger.debug("Getting historical alarms....")
        alarm_object_list = self.factory.admin.get_historical_alarms(
            severity, load_history=load_history, timeout=timeout, connection=alias)
        self.alarm_details = alarm_object_list
        self._write_alarms_to_file('history_alarms.json', alarm_object_list)
        self._verify_alarm_exists_and_validate_with_rise(
            alarm_object_list, check_unexpected_alarms, prev_alarms,
            expected_alarms, faultid, occurrences, should_exist, alias)
        return alarm_object_list

    def _verify_alarm_exists_and_validate_with_rise(self, alarm_object_list,
                                                    check_unexpected_alarms,
                                                    prev_alarms,
                                                    expected_alarms, faultid,
                                                    occurrences, should_exist,
                                                    alias):
        unexpected_alarms = self._get_unexpected_alarms(alarm_object_list,
                                                        prev_alarms, faultid,
                                                        expected_alarms)
        found_occurences = self._verify_alarm_exists(alarm_object_list,
                                                     faultid)
        rise_alarm_found, rise_validation_pass = None, None
        if faultid is not None:
            rise_alarm_found, rise_validation_pass =\
                self._verify_alarm_against_rise(alarm_object_list, faultid,
                                                alias)
        self._raise_exceptions(faultid, should_exist, found_occurences,
                               occurrences, rise_alarm_found,
                               rise_validation_pass, check_unexpected_alarms,
                               unexpected_alarms)

    def _verify_alarm_exists(self, alarm_object_list, faultid):
        logger.debug("Verifying if alarms exist...")
        found_occurences = 0
        if faultid is not None:
            self.alarm_details = list()
            for alarm_obj in alarm_object_list:
                if alarm_obj['faultId'] == int(faultid):
                    found_occurences += 1
                    self.alarm_details.append(alarm_obj)
        logger.debug("Alarm occurences :: {}".format(found_occurences))
        print("alarms details {}".format(self.alarm_details))
        return found_occurences

    def _get_unexpected_alarms(self, alarm_object_list, alarms_for_comparison,
                               given_faultid, expected_alarms):
        if expected_alarms is None:
            expected_alarms = []
        if given_faultid is not None:
            expected_alarms.append(int(given_faultid))

        if alarms_for_comparison:
            cur_fault_ids = [alarm['faultId'] for alarm in alarm_object_list if
                             alarm['faultId'] not in expected_alarms]
            logger.info('cur_fault_ids: {}'.format(cur_fault_ids))
            past_fault_ids =\
                [alarm['faultId'] for alarm in alarms_for_comparison if
                 alarm['faultId'] not in expected_alarms]
            logger.info('past_fault_ids: {}'.format(past_fault_ids))
            unexpected_alarms = [f_id for f_id in cur_fault_ids if
                                 f_id not in past_fault_ids]
        else:
            unexpected_alarms = [alarm['faultId'] for alarm in alarm_object_list
                                 if alarm['faultId'] not in expected_alarms]
        return unexpected_alarms

