    def _raise_exceptions(self, faultid, should_exist, found_occurences,
                          req_occurrences, rise_alarm_found,
                          rise_validation_status, check_unexpected_alarms,
                          unexpected_alarms):
        if check_unexpected_alarms and len(unexpected_alarms) > 0:
            raise UnexpectedAlarmsFoundException('Alarms {}'.format(
                unexpected_alarms))

        if faultid is not None:
            if should_exist is False:
                if found_occurences > 0:
                    raise AlarmShouldNotExistException('Alarms {}'.format(
                        faultid))
            else:
                if found_occurences == 0:
                    raise AlarmNotFoundException
                elif found_occurences >= req_occurrences:
                    if rise_alarm_found is False:
                        raise AlarmNotFoundInRise
                    else:
                        if rise_validation_status is False:
                            raise AlarmRiseValidationFailed
                        else:
                            logger.debug('Rise Validation Success')
                    if found_occurences > req_occurrences:
                        logger.debug('More Alarms {} found than expected'
                                     ' {}'.format(found_occurences,
                                                  req_occurrences))
                        raise MoreThanRequiredAlarmsFound
                elif found_occurences < req_occurrences:
                    raise AllAlarmOccurencesNotFoundException(
                        'Expected: {}, Found: {}'.format(req_occurrences,
                                                         found_occurences))

    def _write_alarms_to_file(self, file_name, alarm_objects_list):
        alarms_file_name = 'execution_logs/{}'.format(file_name)
        if not os.path.exists(os.path.dirname(alarms_file_name)):
            os.makedirs(os.path.dirname(alarms_file_name))
        with open(alarms_file_name, 'a') as alarms_file:
            logger.debug("Writing alarms to {}".format(alarms_file_name))
            alarms_file.write('\n\n=========================================================\n\n')
            json.dump(alarm_objects_list, alarms_file)

    def _verify_alarm_against_rise(self, alarm_object_list, faultid, alias):
        rise_alarm_found = False
        rise_validation_pass = True
        rise_csv = get_config_variable(['rise_csv'])
        rise_header_fields = get_config_variable(['rise_header_fields'])
        for alarm_obj in alarm_object_list:
            alarm_faultid, alarm_faultname, alarm_id, alarm_name = \
                self._get_params_from_alarm_obj(alarm_obj)
            if int(faultid) == alarm_faultid:
                logger.info('given faultid: {}, foundid: {}'.format(
                    faultid, alarm_faultid))
                rise_csv = get_resource_file(rise_csv)
                # rise_csv = os.path.join(self.config["config_path"],
                #                         'rise.csv')
                with open(rise_csv) as rise_fh:
                    reader = csv.DictReader(rise_fh,
                                            fieldnames=rise_header_fields)
                    for rise_row in reader:
                        alarm_rise_match = re.search(r'^-?\s*{}:\s*.*\n?'.format(alarm_faultid),
                                                     rise_row['Fault ID and Fault ID Name'])
                        if alarm_rise_match is not None:
                            logger.debug('Rise match found')
                            logger.debug('ADMIN alarm_faultid: {}'.format(
                                alarm_faultid))
                            logger.debug('RISE faultid_and_name: {}'.format(
                                rise_row['Fault ID and Fault ID Name']), '\n')
                            rise_alarm_found = True
                            rise_validation_pass = self._verify_alarmname_in_rise_reported_alarms(
                                alarm_id, alarm_name, rise_row, rise_validation_pass, alias)
                            rise_validation_pass = self._verify_faultname_in_rise(
                                alarm_faultname, rise_row, rise_validation_pass)
                            return rise_alarm_found, rise_validation_pass
        return rise_alarm_found, False

    def _verify_faultname_in_rise(self, alarm_faultname, rise_row, rise_validation_pass):
        rise_fault_name = rise_row['Fault name']
        logger.debug('ADMIN Fault_name: {}'.format(alarm_faultname))
        logger.debug('RISE fault_name: {}'.format(rise_fault_name), '\n')
        if '$' not in rise_fault_name:  # If strings like $unit exist ignore this column
            if alarm_faultname.strip() != rise_fault_name.strip():
                logger.debug(
                    "Rise validation failed for faultName. \t\t\nADMIN:{}\t\t\nRISE:{}".format(
                        alarm_faultname, rise_fault_name))
                rise_validation_pass = False
        return rise_validation_pass

    def _verify_alarmname_in_rise_reported_alarms(self, alarm_id,
                                                  admin_alarm_name, rise_row,
                                                  rise_validation_pass, alias):
        param_path = 'FMCADM-1:actCategoryAlarms'
        act_category_alarms = self.parameters.get_parameter(param_path=param_path, alias=alias)
        logger.info('actCategoryAlarms: {}'.format(act_category_alarms))
        rise_reported_alarms = rise_row['Reported alarms']
        rise_reported_alarms_desc = rise_row['Reported alarms description']
        logger.debug('ADMIN alarm_id: {}'.format(alarm_id))
        logger.debug('ADMIN alarm_name: {}'.format(admin_alarm_name))
        logger.debug('RISE Reported alarms: {}'.format(rise_reported_alarms), '\n')
        logger.debug('RISE Reported alarms desc: {}'.format(rise_reported_alarms_desc), '\n')

        if act_category_alarms is not None:
            rise_reported_alarms_for_true = re.findall(r'true\).*?({}\s*{}).*?if'.format(
                alarm_id, admin_alarm_name), rise_reported_alarms_desc, (re.DOTALL | re.I))
            rise_reported_alarms_for_false = re.findall(r'false\).*?({}\s*{}).*?'.format(
                alarm_id, admin_alarm_name), rise_reported_alarms_desc, (re.DOTALL | re.I))
            if len(rise_reported_alarms_for_true) != 0 or len(rise_reported_alarms_for_false) != 0:
                rise_validation_pass = getattr(self, '_verify_rise_actcategoryalarms_{}'.format(
                    str(act_category_alarms).lower()))(act_category_alarms, admin_alarm_name,
                                                     rise_reported_alarms_for_false,
                                                     rise_reported_alarms_for_true,
                                                     rise_validation_pass)
            else:
                rise_validation_pass = self._verify_rise_without_actcategoryalarms(
                    admin_alarm_name, alarm_id, rise_reported_alarms, rise_validation_pass)
        else:
            rise_validation_pass = self._verify_rise_without_actcategoryalarms(
                admin_alarm_name, alarm_id, rise_reported_alarms, rise_validation_pass)
        return rise_validation_pass

    def _verify_rise_without_actcategoryalarms(self, admin_alarm_name, alarm_id,
                                               rise_reported_alarms, rise_validation_pass):
        if '$' not in rise_reported_alarms:
            rise_reported_alarms_matched = re.findall(r'.*?({}\s*{}).*?'.format(alarm_id,
                                                                                admin_alarm_name),
                                                      rise_reported_alarms, (re.DOTALL | re.I))
            if len(rise_reported_alarms_matched) == 0:
                rise_validation_pass = False
                logger.warn('ADMIN alarmname {} not found in RISE reported alarms'.format(
                    admin_alarm_name))
            return rise_validation_pass
        else:
            logger.info('Ignored reported alarms with $')

    def _verify_rise_actcategoryalarms_true(self, act_category_alarms, admin_alarm_name,
                                            rise_reported_alarms_for_false,
                                            rise_reported_alarms_for_true, rise_validation_pass):
        if len(rise_reported_alarms_for_true) == 0:
            rise_validation_pass = False
            logger.warn('actCategoryAlarms {}, alarm {} match not found in RISE true category'
                        .format(act_category_alarms, admin_alarm_name))
        if len(rise_reported_alarms_for_false) != 0:
            rise_validation_pass = False
            logger.warn('actCategoryAlarms {}, alarm {} match found in RISE false category'
                        .format(act_category_alarms, admin_alarm_name))
        logger.info('actCategoryAlarms {}, alarm {} match found in RISE true category'
                    .format(act_category_alarms, admin_alarm_name))
        return rise_validation_pass

    def _verify_rise_actcategoryalarms_false(self, act_category_alarms, admin_alarm_name,
                                             rise_reported_alarms_for_false,
                                             rise_reported_alarms_for_true, rise_validation_pass):
        if len(rise_reported_alarms_for_false) == 0:
            rise_validation_pass = False
            logger.warn('actCategoryAlarms {}, alarm {} match not found in RISE false category'
                        .format(act_category_alarms, admin_alarm_name))
        if len(rise_reported_alarms_for_true) != 0:
            rise_validation_pass = False
            logger.warn('actCategoryAlarms {}, alarm {} match found in RISE true category'
                        .format(act_category_alarms, admin_alarm_name))
        logger.info('actCategoryAlarms {}, alarm {} match found in RISE false category'
                    .format(act_category_alarms, admin_alarm_name))
        return rise_validation_pass

    def _get_params_from_alarm_obj(self, alarm_obj):
        alarm_faultid = alarm_obj['faultId']
        alarm_id = alarm_obj['alarmId']
        alarm_name = alarm_obj['alarmName']
        alarm_faultname = alarm_obj['faultName']
        return alarm_faultid, alarm_faultname, alarm_id, alarm_name
